/* ── formatting ─────────────────────────────────────────────── */
const fT = (ms) => (ms == null || isNaN(ms) ? '–:–' : new Intl.DateTimeFormat('es-ES', { timeZone: TZ, hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).format(ms));
