  setV('h1', T().h1(rel(st.night), st.night)); setV('figWhen', T().when(rel(st.night), st.night));
  const fb = eveningDates()[0]; setV('tourANext', T().next(rel(fb), fb)); setV('pickupFirst', fT(night(fb).pickup));
  const sh = $('#moon-shade'); if (sh) sh.setAttribute('d', moonShade(n.k, n.waxing));
