  const n = night(st.night), t0 = n.astro, t1 = n.ret; cancelAnimationFrame(raf);
  const bar = $('.rail__expo'), gauge = $('.gauge');
  const setE = (e) => { if (bar) bar.style.setProperty('--expo', e.toFixed(3)); if (gauge) gauge.style.setProperty('--expo', e.toFixed(3)); };
  if (RM.matches || full === 'static') { sky.draw(t0, t1, 1, n); setE(1); return; }
  const start = performance.now(), A = full ? 900 : 0, B = full ? 2600 : 1300;
  const ease = (x) => 1 - Math.pow(1 - x, 3);
