  fillSelect($('#b-date'), ev, 'atardecer', st.night);
  renderNight(); renderBooking();

  $('#x-date').addEventListener('change', (e) => { if (e.target.value) { setNight(e.target.value); if (st.tour === 'atardecer') $('#b-date').value = e.target.value; } renderBooking(); });
  $('#b-date').addEventListener('change', (e) => { const v = e.target.value; if (v && st.tour === 'atardecer') { setNight(v); $('#x-date').value = v; } renderBooking(); });
  ['x', 'b'].forEach((p) => { $(`#${p}-adults`).addEventListener('change', () => { syncCounts(p); renderBooking(); }); $(`#${p}-kids`).addEventListener('change', () => { syncCounts(p); renderBooking(); }); $(`#${p}-zone`).addEventListener('change', (e) => { st.zone = e.target.value; ['x', 'b'].forEach((q) => { $(`#${q}-zone`).value = st.zone; }); renderBooking(); }); });
  $('#b-name').addEventListener('input', (e) => { st.name = e.target.value; renderBooking(); });
  $$('input[name="tour"]').forEach((r) => r.addEventListener('change', () => { if (!r.checked) return; st.tour = r.value; fillSelect($('#b-date'), datesFor(st.tour), st.tour, st.tour === 'atardecer' ? st.night : ''); const v = $('#b-date').value; if (v && st.tour === 'atardecer') { setNight(v); $('#x-date').value = v; } renderBooking(); }));
  $$('[data-pick]').forEach((b) => b.addEventListener('click', () => { const r = $(`input[name="tour"][value="${b.dataset.pick}"]`); r.checked = true; r.dispatchEvent(new Event('change')); const sec = $('#reservar'); sec.scrollIntoView({ behavior: RM.matches ? 'auto' : 'smooth', block: 'start' }); setTimeout(() => $('#b-date').focus({ preventScroll: true }), RM.matches ? 0 : 450); }));
