  const tc = $('#t-coast'); const tUpd = () => { const c = +tc.value; setV('tCoast', T().temp(c)); setV('tLlano', T().tl(Math.round(c - 6.5 * 1.99))); };
  tc.addEventListener('input', tUpd); tUpd();

  // scroll-spy for the rail / chip bar
  const links = $$('.rail__nav a[href^="#"]'), nav = $('.rail__nav');
  const io = new IntersectionObserver((es) => es.forEach((en) => { if (!en.isIntersecting) return; const id = '#' + en.target.id; links.forEach((a) => { const on = a.getAttribute('href') === id; if (on) a.setAttribute('aria-current', 'location'); else a.removeAttribute('aria-current'); if (on && nav.scrollWidth > nav.clientWidth + 4) nav.scrollTo({ left: nav.scrollLeft + a.getBoundingClientRect().left - nav.getBoundingClientRect().left - 22, behavior: RM.matches ? 'auto' : 'smooth' }); }); }), { rootMargin: '-40% 0px -55% 0px' });
  $$('main > section[id]').forEach((s) => io.observe(s));
  setInterval(tickNow, 60000);

